from math import isqrt, gcd
from fractions import Fraction

def verify(witness):
    m = witness['m']
    primes_q = witness['primes_q']
    offsets_j = witness['offsets_j']
    moduli = witness['moduli']
    residues = witness['residues']
    Q_w = witness['Q']
    n0 = witness['crt_solution_n0']

    def isprime(k):
        if k < 2:
            return False
        for p in range(2, isqrt(k) + 1):
            if k % p == 0:
                return False
        return True

    if len(primes_q) != m:
        raise ValueError('m primes')
    if len(set(primes_q)) != m:
        raise ValueError('distinct primes')
    for q in primes_q:
        if not isprime(q):
            raise ValueError('not prime')
    for q in primes_q:
        if not (q * q > m):
            raise ValueError('q not > sqrt(m)')
    for j in offsets_j:
        if not (1 <= j <= m):
            raise ValueError('offset range')
    for i in range(m):
        if moduli[i] != primes_q[i] * primes_q[i]:
            raise ValueError('modulus')
        if residues[i] != (-offsets_j[i]) % moduli[i]:
            raise ValueError('residue n = -j mod q^2')
    for i in range(m):
        for k in range(i + 1, m):
            if gcd(moduli[i], moduli[k]) != 1:
                raise ValueError('moduli not coprime')
    Q = 1
    for mo in moduli:
        Q *= mo
    if Q != Q_w:
        raise ValueError('Q product')
    for i in range(m):
        if (n0 + offsets_j[i]) % moduli[i] != 0:
            raise ValueError('CRT solution check')
    dens = Fraction(1, 1)
    for q in primes_q:
        dens *= Fraction(q * q - 1, q * q)
    if not (dens > 0):
        raise ValueError('density')
    return True
